   "id": "z67848839",
   "sez": "sport",
   "titolo": "Shanghai, Davidovich Fokina batte Zverev: finale tutta spagnola con Jódar",
   "orig": "Davidovich Fokina stuns top seed Zverev to reach Shanghai Masters final",
   "lead": "Lo spagnolo Alejandro Davidovich Fokina, numero 26 del mondo, ha battuto in rimonta il tedesco Alexander Zverev, prima testa di serie, nella semifinale del Masters 1000 di Shanghai, con il punteggio di 5-7, 6-4, 6-3. In finale troverà il connazionale Rafael Jódar, ventenne, che ha superato il russo Daniil Medvedev 6-3, 6-4 in una partita in cui Medvedev ha discusso con gli arbitri. Sarà quindi una finale spagnola in un torneo che nessun tennista spagnolo ha mai vinto.",
   "more": [
    "I Masters 1000 sono i tornei più importanti del circuito maschile dopo i quattro Slam. Shanghai è l'appuntamento principale della stagione asiatica autunnale e assegna molti punti per la classifica mondiale."
   ],
