   "id": "z02fad2a4",
   "sez": "ingegneria",
   "titolo": "Stirling Prize 2026 alle case popolari di Lion Green Road a Croydon",
   "orig": "This week we revealed the Stirling Prize winner",
   "lead": "Il complesso residenziale di Lion Green Road, a Croydon, nel sud di Londra, ha vinto il RIBA Stirling Prize 2026, il riconoscimento al miglior nuovo edificio del Regno Unito. Il progetto, firmato da Mary Duggan Architects con RUFFARCHITECTS e commissionato dal Comune di Croydon, comprende 157 abitazioni distribuite in cinque edifici. Il premio è stato assegnato durante una cerimonia a Londra. The Architects' Journal definisce la vittoria quella di un outsider e segnala l'accoglienza positiva, anche come segnale per la leadership femminile. Dezeen dà conto anche del RIBA International Prize, vinto da una fabbrica di tappeti in Bangladesh.",
   "more": [
    "Lo Stirling Prize è assegnato ogni anno dal Royal Institute of British Architects ed è il principale premio di architettura del Regno Unito. Che vinca un intervento di edilizia residenziale promosso da un ente locale è significativo in un Paese dove la carenza di case a prezzi accessibili è da anni al centro del dibattito pubblico."
   ],
