     "n": "Turisti per Caso",
     "p": "IT",
     "c": "Milano",
     "u": "https://turistipercaso.it/destinazioni/rieti-il-borgo-natale-di-lucio-battisti-dove-musica-e-natura-regalano-momenti-dautore.html",
