   "sez": "ambiente",
   "titolo": "Kuala Lumpur, nel lago di Ampang il 95% dei pesci è alieno: il governo vieta di liberarli",
   "orig": "Stop dumping pet fish in lakes, govt warns as alien species wiping out natives in Ampang lake",
   "lead": "Il governo malese ha lanciato un appello a non liberare nei laghi i pesci d'acquario. Nel lago di Ampang Hilir, a Kuala Lumpur, le specie aliene rappresentano ormai il 95% dei pesci censiti e stanno soppiantando quelle autoctone, con una grave minaccia per l'equilibrio dell'ecosistema. L'avvertimento, diffuso il 17 ottobre, punta a fermare una pratica diffusa tra chi si disfa degli animali domestici. Lo riferisce Malay Mail.",
   "more": [
    "Le specie aliene invasive sono tra le principali cause di perdita di biodiversità nel mondo. Pesci ornamentali rilasciati in natura possono competere con quelli locali per il cibo, predarli o diffondere malattie. Una volta stabilite, queste popolazioni sono molto difficili e costose da eliminare."
   ],
