   "sez": "sport",
   "titolo": "Petra Kvitová torna in campo sette mesi dopo la nascita dei gemelli",
   "orig": "Petra Kvitová returns to tennis courts seven months after giving birth to twins",
   "lead": "La tennista ceca Petra Kvitová è tornata sui campi da tennis sette mesi dopo aver dato alla luce due gemelli. Il rientro dell'atleta, tra le giocatrici più note del suo Paese, arriva dopo una pausa legata alla maternità ed è seguito con attenzione dal pubblico ceco. La notizia segna la ripresa dell'attività per una sportiva che ha scelto di rimettersi in gioco dopo la nascita dei figli. Lo riferisce Radio Prague International.",
   "more": [
    "Petra Kvitová ha vinto due volte il torneo di Wimbledon, nel 2011 e nel 2014, ed è stata numero due del ranking mondiale. Negli ultimi anni il circuito femminile ha introdotto tutele per le giocatrici che si fermano per maternità, come la classifica protetta al rientro."
   ],
